import{_ as e,a as o,o as d,a6 as a}from"./chunks/framework.CJDy2q7X.js";const h=JSON.parse('{"title":"Catalog Attribute Family — Detail","description":"","frontmatter":{"outline":false,"apiType":"rest","examples":[{"id":"admin-catalog-family-detail","title":"Attribute Family Detail (with attribute groups and attributes)","description":"Single attribute family record including all attribute groups and — within each group — all associated attributes with their pivot position. Use this to populate the edit form in Catalog → Attribute Families.","query":"curl -X GET \\"https://your-domain.com/api/admin/catalog/families/1\\" \\\\\\n  -H \\"Authorization: Bearer <token>\\" \\\\\\n  -H \\"Accept: application/json\\"\\n","variables":"id=1\\n","response":"{\\n  \\"id\\": 1,\\n  \\"code\\": \\"default\\",\\n  \\"name\\": \\"Default\\",\\n  \\"attributeGroups\\": [\\n    {\\n      \\"id\\": 1,\\n      \\"code\\": \\"general\\",\\n      \\"name\\": \\"General\\",\\n      \\"column\\": 1,\\n      \\"position\\": 1,\\n      \\"attributes\\": [\\n        {\\n          \\"id\\": 1,\\n          \\"code\\": \\"sku\\",\\n          \\"type\\": \\"text\\",\\n          \\"isRequired\\": 1,\\n          \\"column\\": 1,\\n          \\"position\\": 1\\n        },\\n        {\\n          \\"id\\": 2,\\n          \\"code\\": \\"name\\",\\n          \\"type\\": \\"text\\",\\n          \\"isRequired\\": 1,\\n          \\"column\\": 1,\\n          \\"position\\": 2\\n        }\\n      ]\\n    }\\n  ]\\n}\\n","commonErrors":[{"error":"Not Found (404)","cause":"The attribute family ID does not exist in the database","solution":"Verify the ID with the listing endpoint `GET /api/admin/catalog/families`"},{"error":"Unauthorized (401)","cause":"Missing, invalid, expired, or revoked admin Bearer token","solution":"Send a valid admin Bearer token (Integration token) in the Authorization header. See the Authentication page."}]}]},"headers":[],"relativePath":"api/rest-api/admin/catalog/families/families-detail.md","filePath":"api/rest-api/admin/catalog/families/families-detail.md","lastUpdated":1787290888000}'),i={name:"api/rest-api/admin/catalog/families/families-detail.md"};function r(n,t,c,s,l,u){return d(),o("div",null,t[0]||(t[0]=[a('<h1 id="catalog-attribute-family-—-detail" tabindex="-1">Catalog Attribute Family — Detail <a class="header-anchor" href="#catalog-attribute-family-—-detail" aria-label="Permalink to &quot;Catalog Attribute Family — Detail&quot;">​</a></h1><p>Returns a single attribute family record by ID, including all <strong>attribute groups</strong> and — within each group — all <strong>attributes</strong> associated via the <code>attribute_group_mappings</code> pivot (with their pivot <code>position</code> and <code>column</code>).</p><p>This is the read endpoint to call when an admin needs the complete structure of an attribute family — e.g. when opening the edit form in the <strong>Catalog → Attribute Families</strong> UI.</p><h2 id="endpoint" tabindex="-1">Endpoint <a class="header-anchor" href="#endpoint" aria-label="Permalink to &quot;Endpoint&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Endpoint</th><th>Method</th><th>Authentication</th></tr></thead><tbody><tr><td><code>/api/admin/catalog/families/{id}</code></td><td>GET</td><td>Admin Bearer token</td></tr></tbody></table><p><code>{id}</code> must be a positive integer. Non-numeric values are rejected by a route requirement (<code>\\d+</code>) — this prevents the <code>{id}</code> segment from matching any other path under <code>/catalog/families/</code>.</p><h2 id="path-parameter" tabindex="-1">Path Parameter <a class="header-anchor" href="#path-parameter" aria-label="Permalink to &quot;Path Parameter&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td>integer</td><td>Yes</td><td>The numeric attribute family ID</td></tr></tbody></table><h2 id="response-shape" tabindex="-1">Response Shape <a class="header-anchor" href="#response-shape" aria-label="Permalink to &quot;Response Shape&quot;">​</a></h2><p>The response is a single JSON object (not wrapped in <code>{ data }</code>) with the following fields:</p><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td>integer</td><td>Attribute family ID</td></tr><tr><td><code>code</code></td><td>string</td><td>Family code (e.g. <code>default</code>, <code>apparel</code>)</td></tr><tr><td><code>name</code></td><td>string</td><td>Family display name (e.g. <code>Default</code>, <code>Apparel</code>)</td></tr><tr><td><code>attributeGroups</code></td><td>array</td><td>All attribute groups belonging to this family (see below)</td></tr></tbody></table><h3 id="attributegroups-item-shape" tabindex="-1"><code>attributeGroups[]</code> item shape <a class="header-anchor" href="#attributegroups-item-shape" aria-label="Permalink to &quot;`attributeGroups[]` item shape&quot;">​</a></h3><p>Each entry in the <code>attributeGroups</code> array corresponds to one row in <code>attribute_groups</code>:</p><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td>integer</td><td>Attribute group ID</td></tr><tr><td><code>code</code></td><td>string</td><td>Group code (e.g. <code>general</code>, <code>price</code>)</td></tr><tr><td><code>name</code></td><td>string</td><td>Group display name (e.g. <code>General</code>, <code>Price</code>)</td></tr><tr><td><code>column</code></td><td>integer</td><td>Layout column position for the group (typically <code>1</code> or <code>2</code>)</td></tr><tr><td><code>position</code></td><td>integer</td><td>Display order position of the group within the family</td></tr><tr><td><code>attributes</code></td><td>array</td><td>Attributes mapped to this group (see below)</td></tr></tbody></table><h3 id="attributegroups-attributes-item-shape" tabindex="-1"><code>attributeGroups[].attributes[]</code> item shape <a class="header-anchor" href="#attributegroups-attributes-item-shape" aria-label="Permalink to &quot;`attributeGroups[].attributes[]` item shape&quot;">​</a></h3><p>Each entry represents one attribute mapped to the group via <code>attribute_group_mappings</code>:</p><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td>integer</td><td>Attribute ID</td></tr><tr><td><code>code</code></td><td>string</td><td>Attribute code (e.g. <code>sku</code>, <code>name</code>, <code>color</code>)</td></tr><tr><td><code>type</code></td><td>string</td><td>Attribute type (e.g. <code>text</code>, <code>select</code>, <code>boolean</code>)</td></tr><tr><td><code>isRequired</code></td><td>integer</td><td><code>1</code> = required on product forms, <code>0</code> = optional</td></tr><tr><td><code>column</code></td><td>integer</td><td>Layout column position of this attribute within the group</td></tr><tr><td><code>position</code></td><td>integer</td><td>Display order position of this attribute within the group</td></tr></tbody></table><p><code>attributeGroups</code> and the nested <code>attributes</code> arrays arrive as plain inline JSON — no IRI strings, no sub-resource links — so one call returns the family&#39;s whole structure. Every id inside is numeric.</p><h2 id="errors" tabindex="-1">Errors <a class="header-anchor" href="#errors" aria-label="Permalink to &quot;Errors&quot;">​</a></h2><table tabindex="0"><thead><tr><th>HTTP Status</th><th>Cause</th></tr></thead><tbody><tr><td><code>401 Unauthorized</code></td><td>Missing, expired, or revoked admin Bearer token</td></tr><tr><td><code>401 Unauthorized</code></td><td>Missing or invalid admin Bearer token</td></tr><tr><td><code>404 Not Found</code></td><td>The specified <code>{id}</code> does not exist in the database</td></tr></tbody></table><h2 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;Notes&quot;">​</a></h2><ul><li><strong><code>attributeGroups</code> is a plain JSON array</strong>, not a sub-resource IRI. Groups and their nested attributes are embedded directly in the response — no follow-up requests are needed.</li><li><strong><code>attributeGroups</code> is <code>null</code> in listing rows.</strong> The <code>GET /api/admin/catalog/families</code> listing returns only <code>id</code>, <code>code</code>, and <code>name</code>. The full nested payload is only available from this detail endpoint.</li><li><strong>No timestamps.</strong> The <code>attribute_families</code> table has <code>$timestamps = false</code> — there are no <code>createdAt</code> or <code>updatedAt</code> fields on the family itself. The <code>attribute_groups</code> table similarly carries no timestamps.</li><li><strong><code>column</code> and <code>position</code> fields</strong> come from the <code>attribute_group_mappings</code> pivot and control where each attribute is rendered in the product-creation form layout. <code>column</code> is typically <code>1</code> or <code>2</code> (left or right panel); <code>position</code> controls vertical order.</li><li><strong>The <code>{id}</code> route parameter must be a digit.</strong> The route carries a <code>requirements: [&#39;id&#39; =&gt; &#39;\\d+&#39;]</code> constraint — non-numeric path segments are rejected with <code>404</code> before reaching the provider.</li><li><strong>Attribute detail fields are slim.</strong> Only the fields needed for family-structure display are returned per attribute (<code>id</code>, <code>code</code>, <code>type</code>, <code>isRequired</code>, <code>column</code>, <code>position</code>). For the full attribute payload (translations, options, validation), use <code>GET /api/admin/catalog/attributes/{id}</code>.</li></ul>',22)]))}const m=e(i,[["render",r]]);export{h as __pageData,m as default};
